# ─────────────────────────────────────────────────────────────────────────────
# Second validation spreadsheet: a random 200-row sample from the full 1,721-row
# validation set, with Claude's own independent judgment added alongside the
# model's (SPIKE best-live) judgment.
#
# IMPORTANT: claude_* columns are a second LLM's opinion, read directly by
# Claude in conversation (not generated by a further scripted LLM call), NOT
# ground truth. Agreement between claude_misinterpreted and
# model_misinterpreted is a proxy for validation, not a substitute for
# human-coded labels.
#
# ── HOW TO USE ───────────────────────────────────────────────────────────────
#   Rscript build_claude_evaluation_xlsx.R
# ─────────────────────────────────────────────────────────────────────────────

subset_path <- "C:/Users/dlakens/OneDrive - TU Eindhoven/git_repos/llm_p_ci_interpretation/_p_ci_200_subset.rds"
claude_path <- "C:/Users/dlakens/AppData/Local/Temp/claude/c--Users-dlakens-OneDrive---TU-Eindhoven-git-repos-metacheck-new/dbcdeb41-cd1b-4d63-9506-a36ec63bc6c2/scratchpad/claude_judgments.csv"
out_path    <- "C:/Users/dlakens/OneDrive - TU Eindhoven/git_repos/llm_p_ci_interpretation/p_ci_validation_claude_sample.xlsx"

sub    <- readRDS(subset_path)
claude <- read.csv(claude_path, stringsAsFactors = FALSE)

stopifnot(nrow(sub) == nrow(claude))

sub$claude_misinterpreted <- as.logical(claude$claude_misinterpreted)
sub$claude_category       <- ifelse(claude$claude_category == "NA", NA_character_, claude$claude_category)
sub$claude_agrees_with_model <- claude$claude_agrees_with_model
sub$claude_notes          <- claude$claude_notes

# treat the model's own NA (failed extraction) as neither agree nor disagree
sub$claude_agrees_with_model[is.na(sub$model_misinterpreted)] <- NA

n_comparable <- sum(!is.na(sub$claude_agrees_with_model))
n_agree      <- sum(sub$claude_agrees_with_model, na.rm = TRUE)
message("Rows: ", nrow(sub))
message("Comparable rows (model gave a non-NA judgment): ", n_comparable)
message("Agreement: ", n_agree, "/", n_comparable, " = ",
       round(100 * n_agree / n_comparable, 1), "%")

library(openxlsx)
wb <- createWorkbook()
addWorksheet(wb, "claude_evaluation")
writeData(wb, "claude_evaluation", sub)
freezePane(wb, "claude_evaluation", firstRow = TRUE)
saveWorkbook(wb, out_path, overwrite = TRUE)

message("Saved: ", out_path)
message("Rows: ", nrow(sub), " | Columns: ", ncol(sub))
